function lowerKeyMap(obj) {
  const out = {};
  if (!obj || typeof obj !== 'object') return out;
  for (const [k, v] of Object.entries(obj)) {
    const val = Array.isArray(v) ? v[0] : v;
    out[String(k).toLowerCase()] = val != null ? String(val) : '';
  }
  return out;
}

const item = $input.first().json;
const headers = lowerKeyMap(item.headers);
const secret = (process.env.FORMSPREE_WEBHOOK_SECRET || '').trim();
const formExpected = (process.env.FORMSPREE_FORM_HASHID || '').trim();

const root = item.body && typeof item.body === 'object' ? item.body : item;
const formId = root.form != null ? String(root.form) : '';

if (formExpected && formId !== formExpected) {
  throw new Error('[webhook] FORMSPREE_FORM_HASHID no coincide con payload.form');
}

if (secret.length === 0) {
  console.warn('[webhook] FORMSPREE_WEBHOOK_SECRET vacío — sin validación');
  return [{ json: item }];
}

let ok = false;
for (const hn of ['x-paperclip-webhook-token', 'x-formspree-signature', 'x-webhook-secret']) {
  const v = headers[hn];
  if (v && v.trim() === secret) { ok = true; break; }
}

const q = item.query && typeof item.query === 'object' ? item.query : {};
const qtok = q.token ?? q.secret;
const qval = Array.isArray(qtok) ? qtok[0] : qtok;
if (!ok && qval != null && String(qval).trim() === secret) ok = true;

if (!ok) throw new Error('[webhook] Token inválido');

return [{ json: item }];

const item = $input.first().json;
const raw = item.body ?? item;
const body =
  raw && typeof raw.submission === 'object' && raw.submission !== null
    ? raw.submission
    : raw && raw.fields
      ? raw.fields
      : raw;

const nombre = String(body.nombre ?? 'Sin nombre');
const email = String(body.email ?? '');
const empresa = String(body.empresa ?? 'Sin empresa');
const tamano = String(body.tamano_equipo ?? 'No indicado');
const dolor = String(body.dolor_proceso ?? 'No especificado');
const herramientas = String(body.herramientas_actual ?? 'No indicado');
const presupuesto = String(body.presupuesto ?? 'No indicado');
const timeline = String(body.timeline ?? 'No indicado');
const whatsapp = String(body.whatsapp ?? 'No proporcionado');
const recurso = body.recurso_pdf != null ? String(body.recurso_pdf) : 'No';
const sitioWeb = String(body.sitio_web ?? 'No proporcionado');

const priority = timeline === 'inmediato' ? 'high' : 'medium';
const title = `Lead: ${nombre} — ${empresa}`;
const description = [
  '## Lead calificado desde formulario web',
  '',
  `**Contacto:** ${nombre}`,
  `**Email:** ${email}`,
  `**WhatsApp:** ${whatsapp}`,
  `**Empresa:** ${empresa}`,
  `**Sitio web:** ${sitioWeb}`,
  `**Tamaño equipo:** ${tamano}`,
  '',
  `**Dolor principal:** ${dolor}`,
  `**Herramientas actuales:** ${herramientas}`,
  '',
  `**Presupuesto estimado:** ${presupuesto}`,
  `**Urgencia / Timeline:** ${timeline}`,
  `**PDF lead magnet:** ${recurso}`,
  '',
  '---',
  '_Issue automático — jaagsolutions.com_',
].join('\n');

const env = process.env;
const issueBody = {
  title,
  description,
  priority,
  status: 'backlog',
  assigneeAgentId: env.PAPERCLIP_A3_AGENT_ID || null,
  projectId: env.PAPERCLIP_P2_PROJECT_ID || null,
  goalId: env.PAPERCLIP_G2_GOAL_ID || null,
};

const base = (env.PAPERCLIP_URL || 'http://paperclip:3100').replace(/\/$/, '');
const companyId = env.PAPERCLIP_COMPANY_ID || '';
const requestUrl = `${base}/api/companies/${companyId}/issues`;

return [{ json: { issueBody, requestUrl } }];

const j = $input.first().json;
console.log('[n8n] Issue OK:', j.id, j.identifier ?? '');
return $input.all();
